import sys
from collections import defaultdict, deque

def find_centroid(tree, size, node, parent):
    largest_subtree = 0
    centroid = node
    for neighbor in tree[node]:
        if neighbor != parent and size[neighbor] > largest_subtree:
            largest_subtree = size[neighbor]
            centroid = neighbor
    return centroid if largest_subtree <= size[node] // 2 else find_centroid(tree, size, centroid, node)

def dfs(tree, node, parent, depth, depths, subtree_size):
    depths[node] = depth
    subtree_size[node] = 1
    for neighbor in tree[node]:
        if neighbor != parent:
            dfs(tree, neighbor, node, depth + 1, depths, subtree_size)
            subtree_size[node] += subtree_size[neighbor]

def centroid_decomposition(tree, n):
    size = [0] * (n + 1)
    depths = [0] * (n + 1)
    subtree_size = [0] * (n + 1)

    dfs(tree, 1, -1, 0, depths, subtree_size)
    size[1] = subtree_size[1]
    centroid = find_centroid(tree, size, 1, -1)

    max_edges = 0
    best_a, best_b, best_c = 0, 0, 0

    for neighbor in tree[centroid]:
        dfs(tree, neighbor, centroid, 0, depths, subtree_size)
        for node in range(1, n + 1):
            if subtree_size[node] == 0:
                continue
            for other_neighbor in tree[centroid]:
                if other_neighbor != neighbor and subtree_size[other_neighbor] > 0:
                    for third_node in range(1, n + 1):
                        if subtree_size[third_node] == 0:
                            continue
                        current_edges = subtree_size[node] + subtree_size[other_neighbor] + subtree_size[third_node] - 3
                        if current_edges > max_edges:
                            max_edges = current_edges
                            best_a, best_b, best_c = node, other_neighbor, third_node

    return max_edges, best_a, best_b, best_c

